package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0 // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var LoanRecData LoanRec

var loanLines []string
var loanPos int

func parseScaled(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return decimal.New(n, -scale)
}

func parseInt(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	return n
}

func fitDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := d.Truncate(scale)
	scaled := t.Shift(scale).Truncate(0)
	mod := decimal.NewFromInt(1).Shift(int32(intDigits) + scale)
	var rScaled decimal.Decimal
	if scaled.IsNegative() {
		m := scaled.Abs().Mod(mod)
		if m.IsZero() {
			rScaled = decimal.NewFromInt(0)
		} else {
			rScaled = m.Neg()
		}
	} else {
		rScaled = scaled.Mod(mod)
	}
	return rScaled.Shift(-scale)
}

func formatEdited(val decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	fracDigits := len(fracPic)
	t := val.Truncate(int32(fracDigits))
	abs := t.Abs()
	scaled := abs.Shift(int32(fracDigits)).Truncate(0)
	scaledStr := scaled.StringFixed(0)
	if len(scaledStr) > 0 && scaledStr[0] == '-' {
		scaledStr = scaledStr[1:]
	}
	var intStr, fracStr string
	if fracDigits == 0 {
		intStr = scaledStr
		fracStr = ""
	} else {
		if len(scaledStr) <= fracDigits {
			intStr = "0"
			fracStr = strings.Repeat("0", fracDigits-len(scaledStr)) + scaledStr
		} else {
			intStr = scaledStr[:len(scaledStr)-fracDigits]
			fracStr = scaledStr[len(scaledStr)-fracDigits:]
		}
	}
	slots := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			slots++
		}
	}
	if len(intStr) > slots {
		intStr = intStr[len(intStr)-slots:]
	}
	fullDigits := strings.Repeat("0", slots-len(intStr)) + intStr
	var b strings.Builder
	digitIdx := 0
	significant := false
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			d := fullDigits[digitIdx]
			digitIdx++
			if c == 'Z' {
				if d != '0' {
					b.WriteByte(d)
					significant = true
				} else {
					if significant {
						b.WriteByte('0')
					} else {
						b.WriteByte(' ')
					}
				}
			} else {
				b.WriteByte(d)
				if d != '0' {
					significant = true
				}
			}
		} else if c == ',' {
			if significant {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		} else {
			b.WriteByte(c)
		}
	}
	if dot >= 0 {
		b.WriteByte('.')
		b.WriteString(fracStr)
	}
	return b.String()
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			data = []byte{}
		} else {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
	}
	loanLines = nil
	loanPos = 0
	if len(data) > 0 {
		s := string(data)
		parts := strings.Split(s, "\n")
		if strings.HasSuffix(s, "\n") {
			parts = parts[:len(parts)-1]
		}
		for _, p := range parts {
			if len(p) > 0 && p[len(p)-1] == '\r' {
				p = p[:len(p)-1]
			}
			loanLines = append(loanLines, p)
		}
	}
	WsEofFlag = "N"
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if loanPos >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanPos]
	loanPos++
	if len(line) > 21 {
		line = line[:21]
	} else if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	}
	LoanRecData.LrAcct = line[0:6]
	LoanRecData.LrPrincipal = parseScaled(line[6:15], 2)
	LoanRecData.LrRate = parseScaled(line[15:19], 2)
	LoanRecData.LrYears = parseInt(line[19:21])
}

func ProcessPara() {
	tmp := LoanRecData.LrPrincipal.Mul(LoanRecData.LrRate).Mul(decimal.NewFromInt(LoanRecData.LrYears)).Shift(-2)
	rounded := tmp.Round(2)
	WsInterest = fitDecimal(rounded, 9, 2)
	WsTotal = fitDecimal(WsTotal.Add(WsInterest), 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(LoanRecData.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	line := LoanRecData.LrAcct + " " + WsPrinEd + " " + WsIntEd
	fmt.Fprint(os.Stdout, line+"\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Fprint(os.Stdout, "RECORDS: "+countStr+"\n")
	fmt.Fprint(os.Stdout, "TOTAL INTEREST: "+WsTotalEd+"\n")
}

func main() {
	MainPara()
}
